import { readFile, writeFile } from 'node:fs/promises';
import { parseArgs } from 'node:util';
import { resolve } from 'node:path';
import { Store } from './store.js';
import { workInput, workId, chapterNumber, draftInput, LabError } from './schemas.js';
import { z } from 'zod';
const { values, positionals } = parseArgs({ allowPositionals: true, options: { db: { type: 'string', default: 'data/fanren/novel.sqlite' }, work: { type: 'string', default: 'fanren' }, output: { type: 'string' }, 'expected-revision': { type: 'string' }, note: { type: 'string' } } });
const store = new Store(resolve(values.db));
try {
    const id = workId.parse(values.work);
    const [command, arg] = positionals;
    let result;
    switch (command) {
        case 'init':
            result = store.init(workInput.parse(JSON.parse(await readFile(arg ?? 'materials/作品.json', 'utf8'))));
            break;
        case 'show':
            result = { work: store.getWork(id), chapters: store.listChapters(id) };
            break;
        case 'chapter':
            result = store.getChapter(id, chapterNumber.parse(Number(arg)));
            break;
        case 'work-version':
            result = store.getWorkVersion(id, z.number().int().positive().parse(Number(arg)));
            break;
        case 'save': {
            if (!arg)
                throw new LabError('INPUT_REQUIRED', '需要带修订基线的草稿 JSON 文件。');
            result = store.saveDraft(draftInput.parse(JSON.parse(await readFile(arg, 'utf8'))), 'human');
            break;
        }
        case 'update': {
            if (!arg)
                throw new LabError('INPUT_REQUIRED', '需要新的完整作品要求 JSON。');
            const input = workInput.parse(JSON.parse(await readFile(arg, 'utf8')));
            if (input.id !== id)
                throw new LabError('WORK_MISMATCH', '文件作品与 --work 不一致。');
            result = store.updateWork(input, z.number().int().positive().parse(Number(values['expected-revision'])));
            break;
        }
        case 'adopt':
            result = store.adopt(id, chapterNumber.parse(Number(arg)), z.number().int().positive().parse(Number(values['expected-revision'])), z.string().trim().min(1).parse(values.note));
            break;
        case 'export': {
            if (!arg)
                throw new LabError('INPUT_REQUIRED', '需要导出 Markdown 文件路径。');
            const exported = store.exportWork(id);
            await writeFile(resolve(arg), exported.text, 'utf8');
            const { text, ...summary } = exported;
            result = { ...summary, path: resolve(arg) };
            break;
        }
        case 'task':
            if (!arg)
                throw new LabError('INPUT_REQUIRED', '需要任务标识。');
            result = store.getTask(arg);
            break;
        default: throw new LabError('COMMAND', '用法：pnpm lab init | show | chapter 1 | save 草稿.json | update 要求.json --expected-revision N | adopt 1 --expected-revision N --note 理由 | export 草稿.md | task 任务标识 [--db 路径] [--work fanren]');
    }
    const text = JSON.stringify(result, null, 2) + '\n';
    if (values.output)
        await writeFile(resolve(values.output), text, 'utf8');
    else
        process.stdout.write(text);
}
catch (error) {
    console.error(JSON.stringify({ code: error instanceof LabError ? error.code : 'INPUT_ERROR', message: error instanceof Error ? error.message : String(error) }));
    process.exitCode = 1;
}
finally {
    store.close();
}

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import assert from 'node:assert/strict';
import { LabError } from './schemas.js';
export class Store {
    db;
    constructor(path) {
        if (path !== ':memory:')
            mkdirSync(dirname(path), { recursive: true });
        this.db = new DatabaseSync(path, { timeout: 2000 });
        this.db.exec(`
      PRAGMA journal_mode=WAL;
      CREATE TABLE IF NOT EXISTS works(id TEXT PRIMARY KEY, revision INTEGER NOT NULL, content TEXT NOT NULL) STRICT;
      CREATE TABLE IF NOT EXISTS work_versions(work_id TEXT NOT NULL REFERENCES works(id), revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,revision)) STRICT;
      CREATE TABLE IF NOT EXISTS chapters(work_id TEXT NOT NULL REFERENCES works(id), number INTEGER NOT NULL, revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,number)) STRICT;
      CREATE TABLE IF NOT EXISTS chapter_versions(work_id TEXT NOT NULL, number INTEGER NOT NULL, revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,number,revision), FOREIGN KEY(work_id,number) REFERENCES chapters(work_id,number)) STRICT;
      CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, content TEXT NOT NULL) STRICT;
    `);
    }
    close() { this.db.close(); }
    transaction(action) {
        // 读取基线与写入处于同一事务，两个入口不能越过修订检查。
        this.db.exec('BEGIN IMMEDIATE');
        try {
            const result = action();
            this.db.exec('COMMIT');
            return result;
        }
        catch (error) {
            this.db.exec('ROLLBACK');
            throw error;
        }
    }
    init(input) {
        if (this.db.prepare('SELECT id FROM works WHERE id=?').get(input.id))
            throw new LabError('WORK_EXISTS', '作品已存在，初始化不会覆盖它。');
        if (input.outline.some((item, index) => item.number !== index + 1))
            throw new LabError('OUTLINE_ORDER', '大纲章节必须从 1 开始连续排列。');
        return this.transaction(() => {
            const content = JSON.stringify(input);
            this.db.prepare('INSERT INTO works VALUES(?,?,?)').run(input.id, 1, content);
            this.db.prepare('INSERT INTO work_versions VALUES(?,?,?)').run(input.id, 1, content);
            return { ...input, revision: 1 };
        });
    }
    getWork(id) {
        const row = this.db.prepare('SELECT revision,content FROM works WHERE id=?').get(id);
        if (!row)
            throw new LabError('WORK_NOT_FOUND', `没有作品 ${id}，先初始化。`);
        return { ...JSON.parse(row.content), revision: Number(row.revision) };
    }
    listWorks() {
        return this.db.prepare('SELECT revision,content FROM works ORDER BY id').all().map(row => ({ ...JSON.parse(row.content), revision: Number(row.revision) }));
    }
    getChapter(workId, number) {
        this.getWork(workId);
        return this.findChapter(workId, number);
    }
    findChapter(workId, number) {
        const row = this.db.prepare('SELECT content FROM chapters WHERE work_id=? AND number=?').get(workId, number);
        return row ? JSON.parse(row.content) : null;
    }
    updateWork(input, expectedRevision) {
        return this.transaction(() => {
            const current = this.getWork(input.id);
            if (current.revision !== expectedRevision)
                throw new LabError('STALE_WORK', `要求已是 r${current.revision}，请重读后再修改。`);
            if (input.outline.some((item, index) => item.number !== index + 1))
                throw new LabError('OUTLINE_ORDER', '大纲章节必须从 1 开始连续排列。');
            const saved = this.db.prepare('SELECT number FROM chapters WHERE work_id=?').all(current.id);
            if (saved.some(row => !input.outline.some(item => item.number === row.number)))
                throw new LabError('OUTLINE_HAS_SAVED_CHAPTER', '大纲不能静默移除已保存的章节。');
            const revision = current.revision + 1;
            // 改写前保存当前原始资料，修订引用有实际文本可回查。
            this.db.prepare('INSERT INTO work_versions SELECT id,revision,content FROM works WHERE id=? ON CONFLICT(work_id,revision) DO NOTHING').run(current.id);
            const content = JSON.stringify(input);
            this.db.prepare('UPDATE works SET revision=?,content=? WHERE id=?').run(revision, content, current.id);
            this.db.prepare('INSERT INTO work_versions VALUES(?,?,?)').run(current.id, revision, content);
            return { ...input, revision };
        });
    }
    getWorkVersion(id, revision) {
        this.getWork(id);
        const row = this.db.prepare('SELECT content FROM work_versions WHERE work_id=? AND revision=?').get(id, revision);
        if (!row)
            throw new LabError('WORK_VERSION_NOT_FOUND', '没有保存这个资料修订。');
        return { ...JSON.parse(row.content), revision };
    }
    persistChapter(chapter) {
        const content = JSON.stringify(chapter);
        this.db.prepare('INSERT INTO chapters VALUES(?,?,?,?) ON CONFLICT(work_id,number) DO UPDATE SET revision=excluded.revision,content=excluded.content').run(chapter.workId, chapter.number, chapter.revision, content);
        this.db.prepare('INSERT INTO chapter_versions VALUES(?,?,?,?)').run(chapter.workId, chapter.number, chapter.revision, content);
        return chapter;
    }
    listChapters(workId) {
        this.getWork(workId);
        const rows = this.db.prepare('SELECT content FROM chapters WHERE work_id=? ORDER BY number').all(workId);
        return rows.map(row => { const { body, ...chapter } = JSON.parse(row.content); return chapter; });
    }
    saveDraft(input, origin, taskId = null) {
        return this.transaction(() => {
            const work = this.getWork(input.workId);
            if (work.revision !== input.expectedWorkRevision)
                throw new LabError('STALE_WORK', `要求已是 r${work.revision}，请重读后再保存。`);
            if (!work.outline.some(item => item.number === input.chapterNumber))
                throw new LabError('CHAPTER_OUT_OF_SCOPE', '本章不在当前已确认的大纲中。');
            const current = this.findChapter(work.id, input.chapterNumber);
            if ((current?.revision ?? 0) !== input.expectedChapterRevision)
                throw new LabError('STALE_CHAPTER', `正文已是 r${current?.revision ?? 0}，请重读后合并。`);
            const bases = [...input.expectedPreviousRevisions].sort((a, b) => a.number - b.number);
            if (bases.length !== input.chapterNumber - 1 || bases.some((item, index) => item.number !== index + 1))
                throw new LabError('PREVIOUS_BASES_REQUIRED', '需要逐项提供前面全部章节的当前修订。');
            for (const base of bases) {
                const previous = this.findChapter(work.id, base.number);
                if (!previous)
                    throw new LabError('PREVIOUS_CHAPTER_MISSING', `第 ${base.number} 章尚未保存。`);
                if (previous.revision !== base.revision)
                    throw new LabError('STALE_PREVIOUS', `第 ${base.number} 章已经是 r${previous.revision}，请读取当前正文后再续写。`);
            }
            const task = taskId ? this.getTask(taskId) : null;
            if (task && (task.workId !== work.id || task.chapterNumber !== input.chapterNumber))
                throw new LabError('TASK_MISMATCH', '任务与本章不一致。');
            const chapter = { workId: work.id, number: input.chapterNumber, revision: (current?.revision ?? 0) + 1, title: input.title, body: input.body, status: 'draft', workRevision: work.revision, origin, taskId, threadId: task?.threadId ?? null, updatedAt: new Date().toISOString(), previousRevisions: bases, reviewNote: null };
            return this.persistChapter(chapter);
        });
    }
    adopt(workId, number, expectedRevision, note) {
        return this.transaction(() => {
            const work = this.getWork(workId);
            const current = this.findChapter(work.id, number);
            if (!current)
                throw new LabError('CHAPTER_NOT_FOUND', '还没有该章正文。');
            if (current.revision !== expectedRevision)
                throw new LabError('STALE_CHAPTER', `正文已是 r${current.revision}，不能采用旧版本。`);
            return this.persistChapter({ ...current, revision: current.revision + 1, status: 'adopted', origin: 'human', reviewNote: note, updatedAt: new Date().toISOString() });
        });
    }
    exportWork(id) {
        const work = this.getWork(id);
        const rows = this.db.prepare('SELECT content FROM chapters WHERE work_id=? ORDER BY number').all(id);
        const chapters = rows.map(row => JSON.parse(row.content));
        const details = chapters.map(chapter => {
            if (chapter.number > 1)
                assert(chapter.previousRevisions, '连续章节缺少保存时的前文基线');
            const previousChanged = (chapter.previousRevisions ?? []).some(base => this.findChapter(id, base.number)?.revision !== base.revision);
            return { number: chapter.number, revision: chapter.revision, status: chapter.status, workRevision: chapter.workRevision, previousRevisions: chapter.previousRevisions ?? [], reviewNote: chapter.reviewNote ?? null, basisCurrent: chapter.workRevision === work.revision && !previousChanged };
        });
        const text = `# ${work.title}\n\n用途：${work.purpose}\n\n` + chapters.map((chapter, index) => `## 第 ${chapter.number} 章 ${chapter.title}\n\n状态：${chapter.status}，正文 r${chapter.revision}；${details[index].basisCurrent ? '资料基线一致，品质仍需人判断' : '资料有变动，需重新核对'}。\n\n${chapter.reviewNote ? `采用说明：${chapter.reviewNote}\n\n` : ''}${chapter.body}\n`).join('\n');
        return { workId: id, workRevision: work.revision, expectedChapters: work.outline.length, savedChapters: chapters.length, allOutlineChaptersSaved: chapters.length === work.outline.length && chapters.every((chapter, index) => chapter.number === index + 1), chapters: details, text };
    }
    createTask(input) {
        const work = this.getWork(input.workId);
        if (!work.outline.some(item => item.number === input.chapterNumber))
            throw new LabError('CHAPTER_OUT_OF_SCOPE', '任务章节不在大纲中。');
        const now = new Date().toISOString();
        const task = { ...input, threadId: null, state: 'created', createdAt: now, updatedAt: now, error: null, usage: null };
        this.db.prepare('INSERT INTO tasks VALUES(?,?)').run(task.id, JSON.stringify(task));
        return task;
    }
    getTask(id) {
        const row = this.db.prepare('SELECT content FROM tasks WHERE id=?').get(id);
        if (!row)
            throw new LabError('TASK_NOT_FOUND', '任务记录不存在。');
        return JSON.parse(row.content);
    }
    updateTask(id, change) {
        const task = { ...this.getTask(id), ...change, updatedAt: new Date().toISOString() };
        this.db.prepare('UPDATE tasks SET content=? WHERE id=?').run(JSON.stringify(task), id);
        return task;
    }
}

